  <script>
    const carousel = document.getElementById('trendingCarousel');
    const nextBtn = document.getElementById('nextBtn');
    const prevBtn = document.getElementById('prevBtn');

    const scrollAmount = () => Math.max(260, Math.floor(carousel.clientWidth * 0.7));

    nextBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: scrollAmount(), behavior: 'smooth' });
    });

    prevBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: -scrollAmount(), behavior: 'smooth' });
    });

    const faqItems = Array.from(document.querySelectorAll('.faq-item'));

    faqItems.forEach((item) => {
      const btn = item.querySelector('.faq-q');
      btn.addEventListener('click', () => {
        faqItems.forEach((other) => {
          const otherBtn = other.querySelector('.faq-q');
          if (other === item) {
            const willOpen = !other.classList.contains('active');
            other.classList.toggle('active', willOpen);
            otherBtn.setAttribute('aria-expanded', String(willOpen));
          } else {
            other.classList.remove('active');
            otherBtn.setAttribute('aria-expanded', 'false');
          }
        });
      });
    });
  </script>
