      --muted: #b8b8b8;
      --primary: #e50914;
      --primary-hover: #f6121d;
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
      background:
        linear-gradient(180deg, rgba(0,0,0,0.55), rgba(0,0,0,0.8)),
        url('https://images.unsplash.com/photo-1478720568477-152d9b164e26?auto=format&fit=crop&w=1600&q=80') center/cover no-repeat fixed;
      color: var(--text);
      min-height: 100vh;
      display: flex;
      flex-direction: column;
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 1rem clamp(1rem, 4vw, 2.5rem);
      border-bottom: 1px solid rgba(255,255,255,0.08);
      background: rgba(20,20,20,0.6);
      backdrop-filter: blur(8px);
    }

    .brand { font-weight: 900; font-size: 1.5rem; text-decoration: none; color: #fff; }
    .brand span { color: var(--primary); }

    .shell {
      flex: 1;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .panel {
      width: min(440px, 100%);
      background: rgba(18,18,18,0.9);
      border: 1px solid var(--stroke);
      border-radius: 16px;
      padding: clamp(1.2rem, 3vw, 2rem);
      box-shadow: 0 22px 45px rgba(0,0,0,0.5);
    }

    h1 {
      margin: 0 0 1rem;
      font-size: clamp(1.55rem, 4vw, 2rem);
      letter-spacing: -0.5px;
    }

    .form { display: grid; gap: 0.85rem; }

    input {
      width: 100%;
      border-radius: 10px;
      border: 1px solid #3a3a3a;
      background: #111;
      color: #fff;
      padding: 0.9rem 0.95rem;
      font-size: 1rem;
    }

    input:focus { outline: 2px solid rgba(229,9,20,0.7); outline-offset: 1px; }

    .btn {
      margin-top: 0.2rem;
      border: 0;
      border-radius: 10px;
      background: var(--primary);
      color: #fff;
      font-weight: 800;
      padding: 0.9rem 1rem;
      cursor: pointer;
      transition: 160ms ease;
    }

    .btn:hover,
    .btn:focus-visible { background: var(--primary-hover); }

    .help {
      margin-top: 1rem;
      border-top: 1px solid var(--stroke);
      padding-top: 1rem;
    }

    .help-toggle {
      color: #fff;
      background: none;
      border: 0;
      padding: 0;
      font: inherit;
      cursor: pointer;
      text-decoration: underline;
      text-underline-offset: 3px;
    }

    .help-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height 240ms ease;
      color: var(--muted);
      margin-top: 0;
    }

    .help.open .help-content {
      max-height: 160px;
      margin-top: 0.7rem;
    }

    footer {
      text-align: center;
      color: #bdbdbd;
      padding: 1rem;
      font-size: 0.92rem;
      background: rgba(20,20,20,0.72);
      border-top: 1px solid rgba(255,255,255,0.08);
    }
  </style>
</head>
<body>
  <header class="topbar">
    <a class="brand" href="index.html">Stream<span>Wave</span></a>
  </header>

  <main class="shell">
    <section class="panel" aria-labelledby="login-heading">
      <h1 id="login-heading">Sign In</h1>
      <form class="form" action="#" method="post">
        <label for="login-id" style="position:absolute;left:-9999px;">Email or mobile number</label>
        <input id="login-id" name="login" type="text" autocomplete="username" placeholder="Email or mobile number" required />

        <label for="password" style="position:absolute;left:-9999px;">Password</label>
        <input id="password" name="password" type="password" autocomplete="current-password" placeholder="Password" required minlength="6" />

        <button class="btn" type="submit">Continue</button>
      </form>

      <div class="help" id="helpBlock">
        <button class="help-toggle" id="helpToggle" type="button" aria-expanded="false" aria-controls="helpContent">Get help</button>
        <div class="help-content" id="helpContent">
          <p>Forgot your password? Use account recovery on the help centre. For billing or access issues, contact support through your account page.</p>
        </div>
      </div>
    </section>
  </main>

  <footer>
    New to StreamWave? Return to the home page to start your membership.
  </footer>

  <script>
    const helpToggle = document.getElementById('helpToggle');
    const helpBlock = document.getElementById('helpBlock');

    helpToggle.addEventListener('click', () => {
      const isOpen = helpBlock.classList.toggle('open');
      helpToggle.setAttribute('aria-expanded', String(isOpen));
    });
  </script>
</body>
</html>
EOF"}
